// 만든 파일이다. 고치지 말고 tools/make_mcn_motion.py 를 다시 돌린다.
// 원본: ../2026-11-11-mcn-hero/src.html (MCN 첫 화면 시험판 2판). 사무실 사진 한 장에 깊이를 넣어 카메라가 둘러보듯 그린다(20초, 세 장면).
window.McnMotion = {
  img: "data:image/webp;base64,",
  dep: "data:image/png;base64,",
  fs: `precision highp float;
uniform sampler2D img, dep;
uniform vec2 res;
uniform float asp, t, fx;
float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
vec3 shot(vec2 w, vec2 cen, float z, vec2 c, float push){
  vec2 q = w / z + cen;
  vec2 vp = vec2(0.47, 0.56);
  vec2 o = q;
  for (int i = 0; i < 6; i++) {
    float d = texture2D(dep, o).r - 0.38;
    o = q + c * d + (vp - q) * push * d;
  }
  float d = texture2D(dep, o).r;
  float pl = smoothstep(0.80, 0.97, d);
  o += pl * vec2(sin(t * 0.8 + o.y * 9.0) + 0.5 * sin(t * 1.6 + o.x * 13.0), 0.4 * sin(t * 1.1 + o.x * 7.0)) * 0.0016;
  o = clamp(o, 0.002, 0.998);
  return texture2D(img, o).rgb;
}
float prog(float T, float a, float b){ return clamp((T - a + 0.45) / (b - a + 0.9), 0.0, 1.0); }
float vis(float T, float a, float b){ return smoothstep(a - 0.45, a + 0.45, T) * (1.0 - smoothstep(b - 0.45, b + 0.45, T)); }
void main(){
  vec2 uv = gl_FragCoord.xy / res;
  uv.y = 1.0 - uv.y;
  float ra = res.x / res.y;
  vec2 s = ra > asp ? vec2(1.0, asp / ra) : vec2(ra / asp, 1.0);
  vec2 w = (uv - 0.5) * s;
  vec2 sh = vec2((fx - 0.5) * (1.0 - s.x), 0.0);
  sh += vec2(sin(t * 0.83) + 0.5 * sin(t * 1.9), 0.7 * cos(t * 1.17)) * 0.0022;
  float T = mod(t, 20.0);
  float Tw = T < 0.45 ? T + 20.0 : T;
  vec3 col = vec3(0.0);
  float va = max(vis(T, 0.0, 7.0), vis(Tw, 20.0, 27.0));
  if (va > 0.0) { float a = T < 10.0 ? prog(T, 0.0, 7.0) : prog(Tw, 20.0, 27.0);
    col += va * shot(w, vec2(0.41 + 0.19 * a, 0.50 + 0.01 * a) + sh, 1.34 + 0.02 * a, vec2(-0.045 + 0.090 * a, 0.004), 0.05 * a); }
  float vb = vis(T, 7.0, 14.0);
  if (vb > 0.0) { float b = prog(T, 7.0, 14.0);
    col += vb * shot(w, vec2(0.64 - 0.17 * b, 0.52 - 0.02 * b) + sh, 1.52 - 0.06 * b, vec2(0.050 - 0.100 * b, -0.004), 0.03 + 0.03 * b); }
  float vc = max(vis(T, 14.0, 20.0), vis(T + 20.0, 14.0, 20.0));
  if (vc > 0.0) { float c = prog(Tw, 14.0, 20.0);
    col += vc * shot(w, vec2(0.52 - 0.04 * c, 0.60 - 0.20 * c) + sh, 1.36 + 0.03 * c, vec2(0.012 - 0.024 * c, 0.035 - 0.070 * c), 0.02 + 0.07 * c); }
  col /= max(va + vb + vc, 0.001);
  col += (hash(gl_FragCoord.xy + floor(t * 24.0)) - 0.5) * 0.018;
  gl_FragColor = vec4(col, 1.0);
}`
};
// 캔버스에 그린다. 그림을 다 읽으면 캔버스에 ready를 붙인다. active()가 거짓이면 그리지 않고 쉰다(보이지 않을 때 힘을 아낀다).
// 마우스 값은 받지 않는다. 가로 900px 이하에서는 사진의 오른쪽(70%)을 본다(시험판과 같다).
// cv.__draw(초)로 한 장을 그릴 수 있다(확인 도구용). still이 참이면 3초 자리 한 장만 그리고 멈춘다(움직임 줄이기).
window.McnMotion.start = function (cv, active, still) {
  var gl = cv.getContext('webgl', { antialias: false, alpha: false });
  if (!gl) return null;
  function sh(type, src) { var s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s); return s; }
  var pr = gl.createProgram();
  gl.attachShader(pr, sh(gl.VERTEX_SHADER, 'attribute vec2 a;void main(){gl_Position=vec4(a,0.0,1.0);}'));
  gl.attachShader(pr, sh(gl.FRAGMENT_SHADER, window.McnMotion.fs));
  gl.bindAttribLocation(pr, 0, 'a');
  gl.linkProgram(pr);
  if (!gl.getProgramParameter(pr, gl.LINK_STATUS)) return null;
  gl.useProgram(pr);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
  var U = function (n) { return gl.getUniformLocation(pr, n); };
  function tex(unit, src) {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, gl.createTexture());
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, src);
  }
  var im = new Image(), dp = new Image();
  im.src = window.McnMotion.img; dp.src = window.McnMotion.dep;
  Promise.all([im.decode(), dp.decode()]).then(function () {
    tex(0, im); tex(1, dp);
    gl.uniform1i(U('img'), 0); gl.uniform1i(U('dep'), 1); gl.uniform1f(U('asp'), im.naturalWidth / im.naturalHeight);
    var ures = U('res'), ut = U('t'), ufx = U('fx');
    function draw(sec) {
      var cw = cv.clientWidth, ch = cv.clientHeight;
      if (!cw || !ch) return;
      var r = Math.min(window.devicePixelRatio || 1, 1.5), w = Math.min(Math.round(cw * r), 2560), h = Math.round(w * ch / cw);
      if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; gl.viewport(0, 0, w, h); }
      gl.uniform2f(ures, w, h); gl.uniform1f(ut, sec); gl.uniform1f(ufx, cw <= 900 ? 0.7 : 0.5);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    }
    cv.__draw = draw;
    cv.classList.add('ready');
    draw(3);
    if (still) return;
    var t0 = performance.now(), last = 0;
    (function loop(ms) {
      // 쉬던 동안의 시간은 건너뛰지 않고 이어서 돈다(다시 보일 때 장면이 튀지 않게)
      if (active() && !document.hidden) { last += Math.min(0.1, (ms - t0) / 1000); draw(last); }
      t0 = ms;
      requestAnimationFrame(loop);
    })(t0);
  });
  return true;
};
